CREATE COLUMN TABLE "TEST_AP"."WTD3" ("AbsEntry" INTEGER CS_INT NOT NULL , "LineId" INTEGER CS_INT NOT NULL , "WTCode" NVARCHAR(4) NOT NULL , "KeyPart1" NVARCHAR(15) NOT NULL , "KeyPart2" NVARCHAR(15) NOT NULL , "DateFrom" LONGDATE CS_LONGDATE NOT NULL , "DateTo" LONGDATE CS_LONGDATE, "Rate" DECIMAL(21,6) CS_FIXED, "DetailType" NVARCHAR(2) NOT NULL , "DataSource" NVARCHAR(1) DEFAULT 'N', "UpdateDate" LONGDATE CS_LONGDATE, "LogInstanc" INTEGER CS_INT DEFAULT 0, PRIMARY KEY ("AbsEntry", "LineId")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "WTD3_BP" ON "TEST_AP"."WTD3" ( "WTCode" ASC, "KeyPart1" ASC, "KeyPart2" ASC, "DateFrom" ASC, "DetailType" ASC )